    let token = req.cookies?.auth_token

    // Modo 2: Header Authorization Bearer (Postman / APIs)
    if (!token && req.headers.authorization) {
      const parts = req.headers.authorization.split(' ')
      if (parts.length === 2 && parts[0] === 'Bearer') {
        token = parts[1]
      }
    }

